{
  "url": "https://arxiv.org/pdf/2007.16168",
  "prompt": "Quote verbatim the WSA velocity equation and all coefficient values used, where it is applied (radius), what WSA version, and citations for the coefficients. Also title, authors, journal reference."
}

{
  "url": "https://arxiv.org/html/2509.06181v2",
  "prompt": "Quote verbatim the WSA velocity equation(s) and coefficient sets used, with attribution to specific papers (McGregor 2011, Riley 2015, Arge 2003/2004, Wallace, Reiss), including values like V_min, V_max, alpha, beta, w (units), a1, a2. Also authors, title."
}

{
  "url": "https://ar5iv.labs.arxiv.org/html/1511.00427",
  "prompt": "Quote verbatim the solar wind speed equation(s), coefficient values, and the sentence(s) attributing them (Arge 2004, McGregor 2011, etc.), including the radius of application. Title/authors/journal."
}

{
  "query": "\"McGregor et al. (2011)\" WSA \"1/4.5\" OR \"2/9\" coronal hole boundary \"w\" \"β\" ENLIL Helios speed relation coefficients",
  "mode": "extended"
}

{
  "url": "https://www.frontiersin.org/journals/astronomy-and-space-sciences/articles/10.3389/fspas.2023.1105797/xml",
  "prompt": "Extract the table/list of WSA velocity relation coefficient sets attributed to different papers (Arge 2003, Arge 2004, McGregor 2011, Riley 2015, Merkin 2011, Pomoell & Poedts 2018, Reiss 2019/2020, Wallace, etc.), verbatim with all values (V_min, V_max, a1..a8, w units). Also the generic equation form, and the paper's authors/title/year."
}

{
  "url": "https://agupubs.onlinelibrary.wiley.com/doi/full/10.1029/2010JA015881",
  "prompt": "Quote verbatim the calibrated WSA velocity equation and coefficients (w, beta, etc.)."
}

{
  "query": "\"McGregor\" 2011 WSA relation \"240\" \"675\" \"2.8\" \"1.25\" coronal hole boundary distance",
  "mode": "standard"
}

{
  "query": "CCMC WSA model page version 5 velocity equation 21.5 Rs \"arc_ft_bd\" OR \"VELEQN\"",
  "mode": "standard"
}

{
  "url": "https://ccmc.gsfc.nasa.gov/models/WSA~5.4",
  "prompt": "Extract the model description, version, velocity equation and coefficients, and references."
}

{
  "url": "https://ccmc.gsfc.nasa.gov/models/WSA~v.5.2/",
  "prompt": "Extract the model description, version, velocity equation and coefficients, radius at which speed is given (5 Rs, 21.5 Rs), and any notes on version history and coefficients; references."
}

{
  "url": "https://ccmc.gsfc.nasa.gov/models/ENLIL~2.8f/",
  "prompt": "Extract all details about inner boundary conditions, ambient parameter settings (a6b1, a3b2, etc.), g53q5, cone model parameters (d4t1x1), default vfast, vslow, dfast, tfast, bfast, xalpha, velocity reduction; and references and documentation links."
}

{
  "url": "https://ccmc.gsfc.nasa.gov/static/files/ENLIL-Code_description.pdf",
  "prompt": "Extract inner boundary conditions: rules for density, temperature, B, velocity from WSA; default parameters vfast, vslow, dfast, tfast, bfast, xalpha, velocity reduction; meaning of a6b1, g53q5, d4t1x1 or similar run-parameter codes."
}

{
  "query": "ENLIL \"a6b1\" ambient \"vfast\" OR \"dfast\" OR \"tfast\" CCMC WSA-ENLIL parameters",
  "mode": "extended"
}

{
  "url": "https://ccmc.gsfc.nasa.gov/ror/results/viewrun.php?runnumber=Lan_Jian_112717_SH_1",
  "prompt": "Extract verbatim the full parameter list of this run: model version, WSA version, ambient setting code (a6b1), runpar code (g53q5?), resolution, vfast, vslow, vrfast, vrslow, bfast, bscl, dfast, tfast, xalpha, nbrad, gamma, qheat, and any cone parameters (d4t1x1 etc.) and inner boundary radius."
}

{
  "url": "https://ccmc.gsfc.nasa.gov/ror/results/viewrun.php?runnumber=Lan_Jian_112717_SH_1",
  "prompt": "List all hyperlinks (full URLs) on the page, especially the control file link, and any text explaining parameter meanings (e.g., what vrfast/vrslow, bscl, nbrad, g53q5 mean)."
}
